/* Theme tokens: theme.ts sets the --bf-* variables on the root; the fallbacks are the light preset. */
.bfusion-root {
  /* border-box: the 24px license clear-zone must sit INSIDE the visual's height, not below it. */
  width: 100%;
  height: 100%;
  overflow: hidden;
  position: relative;
  box-sizing: border-box;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  background-color: var(--bf-bg, #FFFFFF);
  color: var(--bf-text, #242424);
}
.bfusion-root *,
.bfusion-root *:before,
.bfusion-root *:after {
  box-sizing: border-box;
}
.bfusion-root button {
  font-family: inherit;
}
.pmo-root {
  display: flex;
  flex-direction: column;
  padding-bottom: 0;
}
/* License clear-zone as a real 24px row at the bottom of the column, not an absolute
   overlay over a padding: Power BI does not always honour the root's padding, and
   content then ran under the badge. As a flex row nothing can overlap it. */
.pmo-root > .bfusion-license-badge-wrap {
  position: relative;
  left: auto;
  bottom: auto;
  flex: 0 0 24px;
  height: 24px;
  display: flex;
  align-items: center;
  padding-left: 8px;
  overflow: hidden;
}
.bfusion-landing-wrap {
  width: 100%;
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  background: var(--bf-bg, #FFFFFF);
}
.pmo-content {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px 0 0 10px;
  position: relative;
  overflow: hidden;
}
/* ── Top row: titles + question chips + info ─────────────────────────────── */
/* Only the heatmap may shrink; everything above it keeps its natural height. */
.pmo-top,
.pmo-answer,
.pmo-kpis,
.pmo-sec__head {
  flex: 0 0 auto;
}
.pmo-top {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding-right: 10px;
}
.pmo-titles {
  flex: 0 0 auto;
  max-width: 30%;
}
.pmo-title {
  font-size: var(--pmo-title-font, 14px);
  font-weight: 600;
  color: var(--bf-strong, #1F2A44);
  line-height: 1.25;
}
.pmo-subtitle {
  font-size: var(--pmo-subtitle-font, 11px);
  color: var(--bf-muted, #667079);
}
.pmo-ask {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px 6px;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
}
.pmo-ask__label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--pmo-accent, #E8612A);
  margin-right: 2px;
}
.pmo-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 24px;
  padding: 0 4px 0 10px;
  border-radius: 999px;
  background: var(--bf-surface-alt, #F4F5F7);
  border: 1px solid var(--bf-rule, #E5E7EB);
  color: var(--bf-text, #242424);
  cursor: pointer;
  font-size: var(--pmo-chip-font, 11.5px);
  font-weight: 500;
  white-space: nowrap;
  transition: border-color 0.12s ease, background 0.12s ease;
  /* Active: solid accent fill so the filtered state reads at a glance. */
}
.pmo-chip:hover {
  border-color: var(--pmo-accent, #E8612A);
}
.pmo-chip:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
.pmo-chip__count {
  min-width: 18px;
  height: 16px;
  padding: 0 5px;
  border-radius: 999px;
  background: var(--bf-tile, #FFFFFF);
  color: var(--bf-text, #242424);
  font-size: 10.5px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.pmo-chip__count--none {
  color: #15803D;
}
.pmo-chip--active {
  background: var(--pmo-accent, #E8612A);
  border-color: var(--pmo-accent, #E8612A);
  color: #FFFFFF;
  font-weight: 600;
}
.pmo-chip--active .pmo-chip__count {
  background: #FFFFFF;
  color: #9A3A12;
}
.pmo-chip--active:hover {
  border-color: var(--bf-strong, #1F2A44);
}
.pmo-info {
  flex: 0 0 auto;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid #E3E6EC;
  background: #FFFFFF;
  color: #6B7280;
  font-style: italic;
  font-weight: 700;
  font-size: 11px;
  line-height: 1;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  margin-top: 2px;
  transition: transform 0.12s ease;
}
.pmo-info:hover {
  background: #E8612A;
  color: #FFFFFF;
  transform: scale(1.05);
}
.pmo-info:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 2px;
}
.pmo-info-pop {
  position: absolute;
  top: 34px;
  right: 12px;
  z-index: 50;
  width: 340px;
  max-width: calc(100% - 24px);
  background: var(--bf-tile, #FFFFFF);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-top: 2px solid #E8612A;
  border-radius: 6px;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.14);
  padding: 10px 12px;
  font-size: 11px;
  line-height: 1.45;
  color: var(--bf-text, #242424);
}
.pmo-info-pop ul {
  margin: 6px 0 0;
  padding-left: 16px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.pmo-info-pop__title {
  font-weight: 700;
}
/* ── Answer line ─────────────────────────────────────────────────────────── */
.pmo-answer {
  min-height: 20px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding-right: 10px;
  font-size: 12px;
  color: var(--bf-muted, #667079);
}
.pmo-answer__arrow {
  color: var(--pmo-accent, #E8612A);
  font-weight: 700;
}
.pmo-answer__text {
  color: var(--bf-strong, #1F2A44);
  font-weight: 600;
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.pmo-answer__reset {
  flex: 0 0 auto;
  border: 1px solid var(--pmo-accent, #E8612A);
  background: var(--bf-tile, #FFFFFF);
  color: var(--pmo-accent, #E8612A);
  border-radius: 999px;
  padding: 1px 10px;
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
}
.pmo-answer__reset:hover {
  background: var(--pmo-accent, #E8612A);
  color: #FFFFFF;
}
.pmo-answer__reset:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
.pmo-answer--on {
  background: color-mix(in srgb, #E8612A 8%, transparent);
  border-radius: 4px;
  padding-left: 8px;
}
/* ── KPI cards ──────────────────────────────────────────────────────────── */
.pmo-kpis {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(0, 1fr);
  gap: 8px;
  padding-right: 10px;
}
.pmo-kpi {
  border: 1px solid var(--bf-rule, #E5E7EB);
  background: var(--bf-tile, #FFFFFF);
  padding: 7px 10px 6px;
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
  font: inherit;
  color: inherit;
  text-align: left;
  cursor: pointer;
  border-radius: 0;
  transition: border-color 0.12s ease, box-shadow 0.12s ease;
}
.pmo-kpi:hover {
  border-color: #E8612A;
}
.pmo-kpi:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
.pmo-kpi--active {
  border-color: #E8612A;
  box-shadow: inset 0 0 0 1px #E8612A;
  background: color-mix(in srgb, #E8612A 6%, var(--bf-tile, #fff));
}
.pmo-kpi--lead {
  border-top: 3px solid #E8612A;
  padding-top: 5px;
}
.pmo-kpi__label {
  font-size: var(--pmo-kpi-label, 10px);
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--bf-muted, #667079);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}
.pmo-kpi__label-text {
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
}
.pmo-kpi__value {
  font-size: var(--pmo-kpi-value, 22px);
  font-weight: 600;
  line-height: 1.05;
  color: var(--bf-strong, #1F2A44);
  font-variant-numeric: tabular-nums;
  display: flex;
  align-items: baseline;
  gap: 6px;
  white-space: nowrap;
}
.pmo-kpi__value small {
  font-size: 11px;
  font-weight: 500;
  color: var(--bf-muted, #667079);
}
.pmo-kpi__ctx {
  font-size: 10.5px;
  color: var(--bf-muted, #667079);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.pmo-kpi__rag {
  display: flex;
  gap: 8px;
  align-items: center;
}
.pmo-kpi__rag-item {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-variant-numeric: tabular-nums;
}
.pmo-kpi__rag-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  display: inline-block;
}
.pmo-kpi__rag-dot--none {
  box-shadow: inset 0 0 0 1.2px var(--bf-muted, #667079);
}
.pmo-kpi__rag-note {
  margin-left: auto;
  font-size: 0.9em;
  opacity: 0.8;
  overflow: hidden;
  text-overflow: ellipsis;
}
.pmo-pill {
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.04em;
  padding: 1px 6px;
  border-radius: 999px;
  color: #FFFFFF;
  text-transform: uppercase;
}
.pmo-pill--dark-ink {
  color: #3A2A00;
}
.pmo-gauge {
  position: relative;
  height: 5px;
  border-radius: 3px;
  margin-top: 1px;
}
.pmo-gauge i {
  position: absolute;
  top: -3px;
  width: 2px;
  height: 11px;
  background: var(--bf-strong, #1F2A44);
  border-radius: 1px;
}
.pmo-bar {
  display: flex;
  height: 5px;
  border-radius: 3px;
  overflow: hidden;
  gap: 1px;
  margin-top: 1px;
}
.pmo-bar span {
  display: block;
  height: 100%;
}
.pmo-bar--empty {
  visibility: hidden;
}
/* ── Body: main column | insight strip | decisions panel ─────────────────── */
.pmo-body {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: row;
  position: relative;
}
.pmo-main {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding-right: 10px;
}
.pmo-sec {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-height: 0;
}
.pmo-sec--hm {
  flex: 1 1 auto;
}
.pmo-sec--flow {
  flex: 0 0 auto;
}
.pmo-sec__head {
  display: flex;
  align-items: baseline;
  gap: 8px;
  font-size: 10.5px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--bf-muted, #667079);
  white-space: nowrap;
  overflow: hidden;
}
.pmo-sec__head b {
  color: var(--bf-strong, #1F2A44);
  font-weight: 700;
}
.pmo-sec__desc {
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
  flex: 0 1 auto;
}
.pmo-legend {
  margin-left: auto;
  flex: 0 0 auto;
  display: flex;
  gap: 8px;
  text-transform: none;
  letter-spacing: 0;
  font-size: 10.5px;
  color: var(--bf-muted, #667079);
}
.pmo-legend__item {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.pmo-legend__sw {
  min-width: 13px;
  height: 13px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
  font-style: normal;
  background: transparent;
}
.pmo-legend__sw--a {
  font-style: italic;
  font-family: Georgia, serif;
}
.pmo-legend__sw--pass {
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 2px;
}
.pmo-legend__sw--none {
  background: repeating-linear-gradient(135deg, var(--bf-rule, #E5E7EB) 0 2px, transparent 2px 4px);
  border: 1px solid var(--bf-rule, #E5E7EB);
}
/* Heatmap */
.pmo-hm {
  flex: 1 1 auto;
  min-height: 60px;
  overflow: auto;
  border: 1px solid var(--bf-rule, #E5E7EB);
}
.pmo-hm::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
.pmo-hm::-webkit-scrollbar-thumb {
  background: var(--bf-scroll-thumb, #D0D0D0);
  border-radius: 3px;
}
.pmo-hm__table {
  border-collapse: separate;
  border-spacing: 0;
  width: 100%;
  table-layout: fixed;
  font-size: var(--pmo-hm-font, 11px);
}
.pmo-col-name {
  width: 26%;
}
.pmo-col-stage {
  width: 10%;
}
.pmo-col-score {
  width: 58px;
}
.pmo-col-fails {
  width: 42px;
}
.pmo-th {
  position: sticky;
  top: 0;
  z-index: 2;
  background: var(--bf-surface-alt, #F4F5F7);
  color: var(--bf-text, #242424);
  font-weight: 600;
  font-size: 0.87em;
  padding: 4px 2px;
  vertical-align: bottom;
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
  text-align: center;
  line-height: 1.15;
}
.pmo-th--l {
  text-align: left;
  padding-left: 8px;
}
.pmo-th--r {
  text-align: right;
  padding-right: 6px;
}
.pmo-th--area {
  overflow: hidden;
}
.pmo-th--hl {
  background: color-mix(in srgb, #E8612A 18%, var(--bf-surface-alt, #F4F5F7));
  color: var(--bf-strong, #1F2A44);
  box-shadow: inset 0 -2px 0 #E8612A;
}
.pmo-th--click {
  cursor: pointer;
}
.pmo-th--click:hover {
  color: #E8612A;
}
.pmo-th--click:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: -2px;
}
.pmo-th--active {
  background: color-mix(in srgb, #E8612A 26%, var(--bf-surface-alt, #F4F5F7));
  color: var(--bf-strong, #1F2A44);
  box-shadow: inset 0 -3px 0 #E8612A;
}
.pmo-th__name {
  display: block;
  white-space: normal;
  overflow-wrap: normal;
  word-break: keep-all;
  overflow: hidden;
  text-overflow: ellipsis;
}
.pmo-th__badges {
  display: flex;
  justify-content: center;
  gap: 2px;
  margin-top: 3px;
  flex-wrap: wrap;
}
.pmo-hb {
  font-size: 9px;
  font-weight: 700;
  padding: 0 4px;
  border-radius: 3px;
  color: #FFFFFF;
  line-height: 14px;
  white-space: nowrap;
}
.pmo-hb--w {
  color: #3A2A00;
}
.pmo-hb--ok {
  background: transparent;
  color: var(--bf-muted, #667079);
  font-weight: 500;
}
.pmo-row {
  cursor: pointer;
  outline: none;
}
.pmo-row:hover .pmo-td,
.pmo-row:focus-visible .pmo-td {
  background: var(--bf-surface-alt, #F4F5F7);
}
.pmo-row:focus-visible .pmo-td--name {
  box-shadow: inset 2px 0 0 #D97B29;
}
.pmo-row--dim {
  opacity: 0.45;
}
.pmo-row--sel .pmo-td--name {
  box-shadow: inset 3px 0 0 #E8612A;
  font-weight: 600;
}
.pmo-td {
  height: 1.55em;
  padding: 0 4px;
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.pmo-td--name {
  padding-left: 8px;
  color: var(--bf-text, #242424);
}
.pmo-td--stage {
  color: var(--bf-muted, #667079);
  font-size: 0.92em;
}
.pmo-td--score {
  text-align: right;
  padding-right: 6px;
  font-weight: 600;
  color: var(--bf-strong, #1F2A44);
  font-variant-numeric: tabular-nums;
}
.pmo-td--fails {
  text-align: right;
  padding-right: 8px;
  color: var(--bf-muted, #667079);
  font-variant-numeric: tabular-nums;
}
.pmo-td__name-text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.pmo-link {
  border: 0;
  background: transparent;
  color: var(--bf-muted, #667079);
  padding: 0 0 0 4px;
  cursor: pointer;
  vertical-align: -2px;
  opacity: 0;
}
.pmo-row:hover .pmo-link,
.pmo-row:focus-within .pmo-link {
  opacity: 1;
}
.pmo-link:hover,
.pmo-link:focus-visible {
  color: #E8612A;
  outline: none;
}
.pmo-dot {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  margin-right: 5px;
  vertical-align: 1px;
}
.pmo-cell {
  /* Pictogram only: no fill, the coloured symbol carries the state (set inline from Status colours). */
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
  border-left: 1px solid var(--bf-rule, #E5E7EB);
  text-align: center;
  font-size: 1em;
  font-weight: 700;
  line-height: 1;
  background: transparent;
}
.pmo-cell--problem,
.pmo-cell--fail,
.pmo-cell--warning,
.pmo-cell--advisory {
  cursor: pointer;
}
.pmo-cell--problem,
.pmo-cell--fail {
  font-size: 1.05em;
}
.pmo-cell--advisory {
  font-family: Georgia, serif;
  font-style: italic;
}
.pmo-cell--pass {
  background: transparent;
}
.pmo-cell--na {
  background: repeating-linear-gradient(135deg, transparent 0 4px, var(--bf-rule, #E5E7EB) 4px 5px);
}
.pmo-cell--none {
  background: repeating-linear-gradient(135deg, var(--bf-rule, #E5E7EB) 0 2px, transparent 2px 5px);
}
.pmo-cell--hl {
  background: color-mix(in srgb, #E8612A 7%, transparent);
  box-shadow: inset 2px 0 0 #E8612A, inset -2px 0 0 #E8612A;
}
.pmo-cell:hover {
  background: var(--bf-surface-alt, #F4F5F7);
}
.pmo-cell:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: -2px;
}
/* Amber text on white is ~2:1; darken the unfilled amber symbols in light mode to ~3:1. */
.pmo-root:not(.pmo-dark) .pmo-cell--warning,
.pmo-root:not(.pmo-dark) .pmo-legend__sw--w {
  filter: brightness(0.78) saturate(1.3);
}
.pmo-row--blind .pmo-td--name {
  color: var(--bf-muted, #667079);
  font-style: italic;
}
.pmo-hm__blind td {
  background: var(--bf-surface, #F8F9FB);
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
  padding: 0;
}
.pmo-hm__blind-btn {
  width: 100%;
  text-align: left;
  border: 0;
  background: transparent;
  color: var(--bf-text, #242424);
  font-size: 0.95em;
  padding: 3px 8px;
  cursor: pointer;
}
.pmo-hm__blind-btn:hover,
.pmo-hm__blind-btn:focus-visible {
  color: #E8612A;
  outline: none;
}
.pmo-hm__empty {
  padding: 14px;
  color: var(--bf-muted, #667079);
  text-align: center;
}
/* Group rows: Level 1 › Level 2 › Plan */
.pmo-grp {
  cursor: pointer;
  outline: none;
}
.pmo-grp .pmo-td {
  background: var(--bf-surface, #F8F9FB);
  font-weight: 600;
  color: var(--bf-strong, #1F2A44);
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
}
.pmo-grp--d1 .pmo-td {
  background: var(--bf-surface-alt, #F4F5F7);
}
.pmo-grp:hover .pmo-td,
.pmo-grp:focus-visible .pmo-td {
  background: var(--bf-rule, #E5E7EB);
}
.pmo-grp:focus-visible .pmo-td--name {
  box-shadow: inset 2px 0 0 #D97B29;
}
.pmo-grp__caret {
  display: inline-block;
  width: 12px;
  color: #E8612A;
  font-size: 0.85em;
}
.pmo-grp__count {
  margin-left: 6px;
  font-weight: 500;
  color: var(--bf-muted, #667079);
  font-size: 0.9em;
}
.pmo-cell--grp {
  font-size: 0.9em;
  font-style: normal;
  font-family: inherit;
}
/* Cell flyout */
.pmo-flyout {
  position: absolute;
  z-index: 60;
  width: 290px;
  max-width: calc(100% - 8px);
  pointer-events: none;
  background: var(--bf-tile, #FFFFFF);
  color: var(--bf-text, #242424);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 6px;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.16);
  padding: 8px 10px 9px;
  font-size: 11px;
  line-height: 1.45;
}
.pmo-flyout--pinned {
  pointer-events: auto;
  border-top: 2px solid #E8612A;
}
.pmo-flyout__head {
  display: flex;
  align-items: center;
  gap: 6px;
  font-weight: 700;
  color: var(--bf-strong, #1F2A44);
}
.pmo-flyout__title {
  flex: 1 1 auto;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.pmo-flyout__close {
  border: 0;
  background: transparent;
  color: var(--bf-muted, #667079);
  cursor: pointer;
  padding: 0;
  display: inline-flex;
}
.pmo-flyout__close:hover {
  color: #E8612A;
}
.pmo-flyout__sub {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 2px 0 4px;
  color: var(--bf-muted, #667079);
}
.pmo-flyout__sev {
  font-size: 9.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #FFFFFF;
  padding: 0 6px;
  border-radius: 999px;
  background: var(--bf-muted, #667079);
}
.pmo-flyout__sev--warning {
  color: #3A2A00;
}
.pmo-flyout__text {
  margin: 0 0 4px;
}
.pmo-flyout__label {
  font-size: 9.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--bf-muted, #667079);
  margin-top: 4px;
}
.pmo-flyout__list {
  margin: 2px 0 0;
  padding-left: 15px;
}
.pmo-flyout__action {
  margin: 2px 0 0;
  color: var(--bf-strong, #1F2A44);
  font-weight: 600;
}
.pmo-flyout__facts {
  margin-top: 6px;
  color: var(--bf-muted, #667079);
  font-size: 10.5px;
}
.pmo-flyout__open {
  margin-top: 7px;
  border: 1px solid var(--bf-rule, #E5E7EB);
  background: var(--bf-surface-alt, #F4F5F7);
  color: var(--bf-text, #242424);
  border-radius: 999px;
  padding: 2px 10px;
  font-size: 10.5px;
  cursor: pointer;
}
.pmo-flyout__open:hover,
.pmo-flyout__open:focus-visible {
  border-color: #E8612A;
  outline: none;
}
/* Lifecycle flow */
.pmo-flow {
  display: flex;
  flex-direction: column;
  gap: 3px;
  font-size: var(--pmo-flow-font, 11px);
}
.pmo-flow__chev {
  display: flex;
  gap: 3px;
  height: 48px;
}
.pmo-step {
  flex: 1 1 0;
  min-width: 0;
  border: 0;
  cursor: pointer;
  background: var(--bf-surface-alt, #F4F5F7);
  color: var(--bf-text, #242424);
  text-align: left;
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 50%, calc(100% - 12px) 100%, 0 100%, 12px 50%);
  padding: 4px 16px 4px 22px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 1px;
}
.pmo-step--first {
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 50%, calc(100% - 12px) 100%, 0 100%);
  padding-left: 10px;
}
.pmo-step:hover {
  background: var(--bf-rule, #E5E7EB);
}
.pmo-step:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: -2px;
}
.pmo-step--bott {
  background: color-mix(in srgb, #E8612A 16%, var(--bf-surface-alt, #F4F5F7));
}
.pmo-step--on {
  background: var(--bf-band, #1F2A44);
  color: #FFFFFF;
}
.pmo-step--on .pmo-step__n,
.pmo-step--on .pmo-step__n small {
  color: #FFFFFF;
}
.pmo-step--on .pmo-gate {
  border-color: #FFFFFF;
}
.pmo-step__name {
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  display: flex;
  align-items: center;
  gap: 5px;
}
.pmo-step__n {
  font-size: 1.7em;
  font-weight: 600;
  line-height: 1;
  color: var(--bf-strong, #1F2A44);
  font-variant-numeric: tabular-nums;
  display: flex;
  align-items: baseline;
  gap: 5px;
}
.pmo-step__n small {
  font-size: 0.52em;
  font-weight: 500;
  color: var(--bf-muted, #667079);
}
.pmo-gate {
  width: 8px;
  height: 8px;
  transform: rotate(45deg);
  border: 1.5px solid var(--bf-muted, #667079);
  display: inline-block;
  flex: 0 0 auto;
}
.pmo-flow__meta {
  display: flex;
  gap: 3px;
}
.pmo-flow__cell {
  flex: 1 1 0;
  min-width: 0;
  display: flex;
  gap: 6px;
  align-items: center;
  padding-left: 12px;
  color: var(--bf-muted, #667079);
  font-size: 0.92em;
  white-space: nowrap;
  overflow: hidden;
}
.pmo-flow__cell:first-child {
  padding-left: 4px;
}
.pmo-flow__tag {
  color: #C2410C;
  font-weight: 700;
}
.pmo-dots {
  display: inline-flex;
  gap: 2px;
  align-items: center;
}
.pmo-dots i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  display: inline-block;
}
.pmo-dots .pmo-dots__none {
  background: transparent !important;
  box-shadow: inset 0 0 0 1px var(--bf-muted, #667079);
}
.pmo-dots .pmo-dots__more {
  font-size: 0.9em;
  margin-left: 2px;
}
/* ── Detail list behind a KPI card (side panel) ─────────────────────── */
.pmo-detail__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.pmo-detail__back {
  border: 1px solid var(--bf-rule, #E5E7EB);
  background: var(--bf-tile, #FFFFFF);
  color: var(--bf-text, #242424);
  border-radius: 999px;
  padding: 1px 10px;
  font-size: 0.95em;
  cursor: pointer;
}
.pmo-detail__back:hover,
.pmo-detail__back:focus-visible {
  border-color: #E8612A;
  color: #E8612A;
  outline: none;
}
.pmo-detail__count {
  color: var(--bf-muted, #667079);
  font-size: 0.95em;
}
.pmo-detail__title {
  margin: 2px 0 0;
  font-size: 1.1em;
  font-weight: 600;
  color: var(--bf-strong, #1F2A44);
}
.pmo-detail__note {
  margin: 0;
  color: var(--bf-muted, #667079);
  line-height: 1.35;
}
.pmo-detail__list {
  list-style: none;
  margin: 4px 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
}
.pmo-detail__row {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 5px 4px 5px 0;
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
  outline: none;
}
.pmo-detail__row--project {
  cursor: pointer;
}
.pmo-detail__row--project:hover,
.pmo-detail__row--project:focus-visible {
  background: var(--bf-surface-alt, #F4F5F7);
}
.pmo-detail__row--sel {
  background: color-mix(in srgb, #E8612A 10%, transparent);
}
.pmo-detail__tone {
  flex: 0 0 3px;
  align-self: stretch;
  border-radius: 2px;
}
.pmo-detail__txt {
  flex: 1 1 auto;
  min-width: 0;
}
.pmo-detail__name {
  font-weight: 600;
  color: var(--bf-text, #242424);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* Failed check names can be long: wrap to three lines, the full list is in the tooltip. */
.pmo-detail__sub {
  color: var(--bf-muted, #667079);
  font-size: 0.92em;
  line-height: 1.3;
  white-space: pre-line;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
}
.pmo-detail__cols {
  display: flex;
  align-items: flex-end;
  gap: 8px;
  padding: 6px 4px 3px 11px;
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
  font-size: 0.85em;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--bf-muted, #667079);
}
.pmo-detail__col-name {
  flex: 1 1 auto;
  min-width: 0;
}
.pmo-detail__col-count,
.pmo-detail__count-cell {
  flex: 0 0 46px;
  text-align: right;
}
.pmo-detail__col-val {
  flex: 0 0 auto;
  min-width: 62px;
  text-align: right;
}
.pmo-detail__count-cell {
  font-weight: 700;
  font-size: 1.15em;
  font-variant-numeric: tabular-nums;
  color: var(--bf-strong, #1F2A44);
}
.pmo-detail__count-cell--zero {
  color: var(--bf-muted, #667079);
  font-weight: 500;
}
.pmo-detail__val {
  flex: 0 0 auto;
  min-width: 62px;
  text-align: right;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--bf-strong, #1F2A44);
}
/* ── Insight strip (suite chrome, fixed) ─────────────────────────────────── */
.bfusion-insight-strip {
  flex: 0 0 26px;
  width: 26px;
  background: #f4f5f7;
  border-left: 1px solid #e5e7eb;
  color: #888;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  user-select: none;
  transition: background 0.15s ease, color 0.15s ease;
}
.bfusion-insight-strip__arrow {
  font-size: 10px;
  color: #D97B29;
  line-height: 1;
}
.bfusion-insight-strip__label {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  letter-spacing: 0.18em;
  font-weight: 650;
  color: #aaa;
  text-transform: uppercase;
  font-size: 9px;
}
.bfusion-insight-strip:hover {
  background: #eceef1;
  color: #333;
}
.bfusion-insight-strip:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: -2px;
}
/* ── Decisions panel ────────────────────────────────────────────────────── */
.pmo-panel {
  flex: 0 0 290px;
  max-width: 320px;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 0 10px 0 10px;
  background: linear-gradient(180deg, var(--bf-bg, #FFFFFF) 0%, var(--bf-surface, #F8F9FB) 100%);
  font-size: var(--pmo-insight-font, 11px);
}
.pmo-panel__head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
  padding-bottom: 5px;
  border-bottom: 2px solid var(--pmo-accent, #E8612A);
  font-size: var(--pmo-insight-header-font, 11px);
}
.pmo-panel__title {
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bf-strong, #1F2A44);
}
.pmo-panel__sub {
  color: var(--bf-muted, #667079);
  font-size: 0.95em;
}
.pmo-panel__list {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 7px;
  padding-bottom: 4px;
}
.pmo-panel__list::-webkit-scrollbar {
  width: 6px;
}
.pmo-panel__list::-webkit-scrollbar-thumb {
  background: var(--bf-scroll-thumb, #D0D0D0);
  border-radius: 3px;
}
.pmo-body--insight-collapsed .pmo-panel,
.pmo-body--insight-hidden .pmo-panel,
.pmo-body--insight-hidden .bfusion-insight-strip {
  display: none;
}
.pmo-dec {
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-left: 3px solid var(--pmo-advisory, #2F6FB0);
  background: var(--bf-tile, #FFFFFF);
  padding: 7px 9px 8px;
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-height: 124px;
  flex: 0 0 auto;
  /* Buttons sit on the card's bottom edge, same place on every card. */
}
.pmo-dec__badge {
  align-self: flex-start;
  font-size: 0.82em;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #B45309;
}
.pmo-dec__title {
  margin: 0;
  font-size: 1.1em;
  font-weight: 600;
  line-height: 1.3;
  color: var(--bf-strong, #1F2A44);
}
.pmo-dec__stake {
  margin: 0;
  line-height: 1.38;
  color: var(--bf-text, #242424);
  opacity: 0.85;
}
.pmo-dec__action {
  margin: 0;
  line-height: 1.38;
  color: var(--bf-text, #242424);
}
.pmo-dec__action b {
  color: #E8612A;
}
.pmo-dec__foot {
  margin-top: auto;
  padding-top: 6px;
  display: flex;
  align-items: center;
  gap: 4px;
}
.pmo-dec__show {
  border: 1px solid var(--bf-rule, #E5E7EB);
  background: var(--bf-surface-alt, #F4F5F7);
  color: var(--bf-text, #242424);
  border-radius: 999px;
  font-size: 0.95em;
  font-weight: 600;
  padding: 2px 10px;
  cursor: pointer;
}
.pmo-dec__show:hover {
  border-color: #E8612A;
}
.pmo-dec__show:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
.pmo-dec__show--on {
  background: #E8612A;
  border-color: #E8612A;
  color: #FFFFFF;
}
.pmo-dec__icon {
  margin-left: 2px;
  width: 26px;
  height: 22px;
  border: 1px solid var(--bf-rule, #E5E7EB);
  background: var(--bf-tile, #FFFFFF);
  color: var(--bf-muted, #667079);
  border-radius: 6px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
}
.pmo-dec__icon:first-of-type {
  margin-left: auto;
}
.pmo-dec__icon:hover {
  color: #E8612A;
  border-color: #E8612A;
}
.pmo-dec__icon:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 1px;
}
.pmo-dec__none {
  color: var(--bf-muted, #667079);
  padding: 8px 2px;
}
.pmo-dec__show + .pmo-dec__icon {
  margin-left: auto;
}
.pmo-empty {
  flex: 1 1 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--bf-muted, #667079);
  font-size: 12px;
}
/* ── Responsive (width classes, never @media) ───────────────────────────── */
.pmo-medium,
.pmo-narrow {
  /* Area names turn vertical so a column never breaks a word. */
}
.pmo-medium .pmo-th__name,
.pmo-narrow .pmo-th__name {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  white-space: nowrap;
  max-height: 78px;
  margin: 0 auto;
}
.pmo-medium .pmo-kpi__label,
.pmo-narrow .pmo-kpi__label {
  letter-spacing: 0.02em;
}
.pmo-medium .pmo-kpis {
  grid-auto-flow: row;
  grid-template-columns: repeat(auto-fill, minmax(118px, 1fr));
}
.pmo-medium .pmo-panel {
  flex-basis: 220px;
}
.pmo-medium .pmo-col-name {
  width: 30%;
}
.pmo-medium .pmo-sec__desc {
  display: none;
}
.pmo-medium .pmo-kpi__value {
  font-size: calc(var(--pmo-kpi-value, 22px) * 0.82);
}
.pmo-narrow .pmo-content {
  overflow-y: auto;
}
.pmo-narrow .pmo-titles {
  display: none;
}
.pmo-narrow .pmo-ask {
  flex-wrap: nowrap;
  overflow-x: auto;
  scrollbar-width: thin;
}
.pmo-narrow .pmo-kpis {
  grid-auto-flow: row;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.pmo-narrow .pmo-kpi__ctx,
.pmo-narrow .pmo-gauge,
.pmo-narrow .pmo-bar {
  display: none;
}
.pmo-narrow .pmo-body {
  flex: 0 0 auto;
}
.pmo-narrow .pmo-hm {
  min-height: 240px;
}
.pmo-narrow .pmo-sec__desc,
.pmo-narrow .pmo-legend {
  display: none;
}
.pmo-narrow .pmo-panel {
  position: absolute;
  right: 26px;
  top: 0;
  bottom: 0;
  z-index: 30;
  flex-basis: auto;
  width: 250px;
  box-shadow: -6px 0 16px rgba(0, 0, 0, 0.12);
  background: var(--bf-bg, #FFFFFF);
}
.pmo-narrow .pmo-col-name {
  width: 40%;
}
.pmo-narrow .pmo-flow__meta {
  display: none;
}
/* ── Tooltip / landing / license (suite chrome) ──────────────────────────── */
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FF5500;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: var(--bf-text, #242424);
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  font-weight: 400;
  color: var(--bf-muted, #667079);
  margin: 0;
  padding: 0;
  line-height: 1.5;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: var(--bf-text, #242424);
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: var(--bf-rule, #E5E7EB);
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: var(--bf-muted, #667079);
  margin-bottom: 4px;
  font-weight: 400;
}
.bfusion-landing__metadata a {
  color: var(--bf-muted, #667079);
  text-decoration: none;
}
.bfusion-landing__metadata a:hover {
  text-decoration: underline;
}
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
  line-height: 1;
}
.bfusion-root .bfusion-license-badge {
  position: static;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 0;
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  color: var(--bf-badge, #4B5563);
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-root .bfusion-license-badge em {
  color: #E8612A;
  font-style: normal;
  font-weight: 600;
  opacity: 1;
}
.bfusion-license-badge__icon {
  font-size: 10px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
